mapper.select:
select collect_id, count, is_current
from user_backpack
where user_id = #{userId}

select id, user_id, collect_id, count, is_current, created_at, updated_at
from user_backpack
where user_id = #{userId}
  and collect_id = #{collectId}
limit 1

mapper.insert:
insert into user_backpack (
    user_id, collect_id, count, is_current, created_at, updated_at
) values (
    #{userId}, #{collectId}, #{count}, #{isCurrent}, now(), now()
)

mapper.update:
update user_backpack
set count = count + #{amount},
    updated_at = now()
where user_id = #{userId}
  and collect_id = #{collectId}

update user_backpack
set is_current = 1,
    updated_at = now()
where user_id = #{userId}
  and collect_id = #{collectId}
